 var values=new ArrayList<Object>();try(var b=c.prepareStatement("SELECT DISTINCT b.build_sha,b.document_count"+joins+" AND b.completed_at<=a.created_at")){b.setString(1,attempt);b.setString(2,source);b.setString(3,field.getKey());b.setString(4,field.getValue().asText());try(var rows=b.executeQuery()){while(rows.next())values.add(Map.of("sha",rows.getString(1),"count",rows.getInt(2)));}}checked++;
 if(values.size()!=1){var all=new ArrayList<Object>();try(var b=c.prepareStatement("SELECT b.build_sha,b.document_count,b.completed_at,a.created_at"+joins)){b.setString(1,attempt);b.setString(2,source);b.setString(3,field.getKey());b.setString(4,field.getValue().asText());try(var r=b.executeQuery()){while(r.next())all.add(Map.of("sha",r.getString(1),"count",r.getInt(2),"buildTime",r.getString(3),"attemptTime",r.getString(4)));}}issues.add(Map.of("attempt",attempt,"result",result,"source",source,"field",field.getKey(),"modelVersion",field.getValue().asText(),"acceptedBuilds",values,"allMatchingBuilds",all));}
